def _csv_safe(value: object) -> str:
    """Schutz vor Formel-Injection: Excel führt Zellen mit = + - @ als Formel aus.
    Texte stammen teils aus LLM/Webquellen, daher mit ' entschärfen."""
    text = str(value)
    return "'" + text if text[:1] in ("=", "+", "-", "@", "\t", "\r") else text


